const activity={1:{start:'ch1-change',readiness:'ch1-change',case:'ch1-allocation',lab:'ch1-comparison',finish:'ch1-allocation'},2:{start:'ch2-return',returns:'ch2-return',compound:'ch2-growth',discount:'ch2-discount',inflation:'ch2-inflation',lab:'ch2-transfer',finish:'ch2-transfer'}};
export function pythonLink(chapter,step){const id=activity[chapter]?.[step];if(!id)return '';const prefix=chapter===1?'python/':'../python/';return `<section class="callout" aria-label="Optional Python consolidation"><strong>Consolidate this concept with Python.</strong><p>Read a worked example, edit a small script, run real Python and check your method on changed inputs. <a href="${prefix}?chapter=${chapter}#${id}">Try the related Python activity</a></p><p class="mini">Optional extra practice: about ${chapter===1?'40':'65'} minutes across Chapter ${chapter}, plus first-time setup. Coding progress is saved separately from your core chapter.</p></section>`;}
